import base64,hashlib,json,os,pathlib,subprocess,sys
OUT=pathlib.Path('/kaggle/working/dataset_upload');OUT.mkdir(parents=True,exist_ok=True)
BINDING={'kind': 'dataset_upload', 'source_commit': '642d3736c49313e615a9657bf53032f1ae06fbfd', 'source_sha256': '745204fb3460d78f2ab218b6bbdf7429046a1a9b3b9d2f547d6d9cc2bbdb4fc0', 'module': 'kaggle_dataset_upload_study.py', 'cpu_only': True, 'installs': False, 'h3_runtime_loaded': False, 'core_libraries_unchanged': True, 'credential_values_embedded': False, 'dataset_sources': [], 'kernel_sources': [], 'scope': 'Private synthetic uploads using native clients and ambient/attached-secret auth'}
(OUT/'source_binding.json').write_text(json.dumps(BINDING,indent=2))
assert not list(pathlib.Path('/dev').glob('nvidia[0-9]*')),'CPU-only instance required'
data=base64.b64decode('');assert hashlib.sha256(data).hexdigest()==BINDING['source_sha256']
source=OUT/BINDING['module'];source.write_bytes(data)
argv=[sys.executable,'-u',str(source),'--output',str(OUT)]
if BINDING['kind']=='dataset_read':
 roots=[]
 for slug in [value.split('/')[-1] for value in BINDING['dataset_sources']]:
  direct=pathlib.Path('/kaggle/input')/slug
  found=[direct] if direct.is_dir() else [p for p in pathlib.Path('/kaggle/input').rglob(slug) if p.is_dir()]
  if len(found)!=1:raise RuntimeError('Required dataset mount not uniquely present: '+slug)
  roots.append(str(found[0]))
 argv+=['--roots',*roots]
env=dict(os.environ,CUDA_VISIBLE_DEVICES='')
subprocess.run(argv,env=env,check=True,timeout=650)
